// Environment configuration for non-Firebase secrets.
//
// Firebase keys are auto-generated by `flutterfire configure`
// into `lib/firebase_options_{flavor}.dart` — they are NOT stored here.
//
// To add non-Firebase secrets:
// 1. Add keys to `.env`
// 2. Uncomment the envied code below and add fields
// 3. Run `dart run build_runner build -d`
//
// import 'package:envied/envied.dart';
//
// part 'env.g.dart';
//
// @Envied(path: '.env')
// abstract class Env {
//   @EnviedField(varName: 'SOME_API_KEY', obfuscate: true)
//   static final String someApiKey = _Env.someApiKey;
// }

/// Values passed with `--dart-define-from-file=.env.<flavor>`. No Firebase
/// keys here — they come from firebase_options_{flavor}.dart.
abstract final class Env {
  /// Where crash reports go (Req 68). Not a secret: it only allows sending
  /// reports. Empty means crash reporting is off.
  static const sentryDsn = String.fromEnvironment('SENTRY_DSN');

  /// Debug builds report crashes only with `SENTRY_DEBUG=true`.
  static const sentryDebug = bool.fromEnvironment('SENTRY_DEBUG');
}
